// ArchiSpotter — lotes 02–06: integración no destructiva de contenidos trilingües.
// Conserva imágenes, coordenadas, descripciones largas, favoritos y MP3 existentes.
/* archiEditorial2026: cargado desde data/monuments-data.js */
for (const monument of initialMonumentsData) {
    const update = archiEditorial2026[monument.id];
    if (!update) continue;
    if (update.curiosity_i18n?.es) monument.secret = update.curiosity_i18n.es;
    if (update.architecture_i18n?.es) monument.architecture = update.architecture_i18n.es;
    for (const [lang, dest] of [['en', englishMonumentContent[monument.id]], ['it', italianMonumentContent[monument.id]]]) {
        if (!dest) continue;
        if (update.curiosity_i18n?.[lang]) dest.secret = update.curiosity_i18n[lang];
        if (update.architecture_i18n?.[lang]) dest.architecture = update.architecture_i18n[lang];
    }
}


